/**
 ******************************************************************************
 * @file    test_play_plan.c
 * TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Jack's storage subsystem (best-ui), with an AI coding assistant.
 * @brief   Host tests for play_plan.c: which way a PLAY, RESUME or effect
 *          switch goes, what Jack does when the waited job ends, and the
 *          position sums.
 *
 * Groups:
 *   1. pp_decide: adopt, the source first, files Jack cannot play, the
 *      original, the effect file, prepare, and the "made but not valid" rule
 *   2. pp_on_waited_end: what Jack does when the waited job ends
 *   3. Position and offsets: where an effect switch carries on
 * Pure logic: no card, no fake needed.
 ******************************************************************************/
#include "unity.h"
#include "play_plan.h"
#include <string.h>

void setUp(void) {}
void tearDown(void) {}

/* A PLAY of a 32 kHz recording with Echo: facts known, its effect file
 * checked, the engine fine, the card in the slot. Tests change one fact. */
static pp_facts_t ready_facts(void)
{
    pp_facts_t f;
    memset(&f, 0, sizeof(f));
    f.effect = FXS_EFFECT_ECHO;
    f.have_src = true;
    f.src_result = STORAGE_OK;
    f.playable = true;
    f.renderable = true;
    f.have_check = true;
    f.check = FXJ_VALID;
    f.engine_ok = true;
    f.slot_present = true;
    return f;
}

/* ---------- 1. pp_decide ---------- */

void test_the_same_pair_being_made_is_adopted(void)
{
    pp_facts_t f = ready_facts();
    f.have_src = false;                               /* nothing read yet: none needed */
    f.job_same_pair = true;
    TEST_ASSERT_EQUAL(PP_ADOPT, pp_decide(&f));
}

void test_another_pair_needs_the_source_facts_first(void)
{
    pp_facts_t f = ready_facts();
    f.have_src = false;
    TEST_ASSERT_EQUAL(PP_NEED_SOURCE, pp_decide(&f));
    f.have_src = true;
    f.have_check = false;
    TEST_ASSERT_EQUAL(PP_NEED_CHECK, pp_decide(&f));
}

void test_an_effect_switch_while_preparing_is_another_pair(void)
{
    /* Preparing Echo, the user picks Robot: the running job is not Robot's. */
    pp_facts_t f = ready_facts();
    f.effect = FXS_EFFECT_ROBOT;
    f.job_same_pair = false;
    f.have_check = false;
    TEST_ASSERT_EQUAL(PP_NEED_CHECK, pp_decide(&f));
    /* No effect at all ("None") never adopts a job, even one for that name. */
    f.effect = FXS_EFFECT_NONE;
    f.job_same_pair = true;
    TEST_ASSERT_EQUAL(PP_PLAY_ORIGINAL, pp_decide(&f));
}

void test_files_jack_cannot_play_are_refused_as_today(void)
{
    pp_facts_t f = ready_facts();
    f.playable = false;                               /* stereo, 8-bit, 24-bit */
    TEST_ASSERT_EQUAL(PP_FAIL_FORMAT, pp_decide(&f));
    f = ready_facts();
    f.src_result = STORAGE_CORRUPT;
    TEST_ASSERT_EQUAL(PP_FAIL_HEADER, pp_decide(&f));
    f.src_result = STORAGE_NOT_FOUND;
    TEST_ASSERT_EQUAL(PP_FAIL_NOT_FOUND, pp_decide(&f));
    f.src_result = STORAGE_READ_FAIL;
    TEST_ASSERT_EQUAL(PP_FAIL_READ, pp_decide(&f));
}

void test_a_read_fail_with_an_empty_slot_is_card_removed(void)
{
    pp_facts_t f = ready_facts();
    f.src_result = STORAGE_READ_FAIL;
    f.slot_present = false;
    TEST_ASSERT_EQUAL(PP_FAIL_REMOVED, pp_decide(&f));
}

void test_no_effect_or_a_file_without_effects_plays_the_original(void)
{
    pp_facts_t f = ready_facts();
    f.effect = FXS_EFFECT_NONE;
    TEST_ASSERT_EQUAL(PP_PLAY_ORIGINAL, pp_decide(&f));
    TEST_ASSERT_FALSE(pp_no_fx(&f));                  /* nothing was asked: no "n/a" */

    f = ready_facts();
    f.renderable = false;                             /* 44.1 kHz, or longer than 60 s */
    f.have_check = false;
    TEST_ASSERT_EQUAL(PP_PLAY_ORIGINAL, pp_decide(&f));
    TEST_ASSERT_TRUE(pp_no_fx(&f));
}

void test_a_valid_effect_file_plays_even_while_the_engine_is_stalled(void)
{
    pp_facts_t f = ready_facts();
    f.engine_ok = false;
    TEST_ASSERT_EQUAL(PP_PLAY_FX, pp_decide(&f));
    TEST_ASSERT_FALSE(pp_no_fx(&f));
}

void test_a_check_io_error_is_a_read_fault(void)
{
    pp_facts_t f = ready_facts();
    f.check = FXJ_IO_ERROR;
    TEST_ASSERT_EQUAL(PP_FAIL_READ, pp_decide(&f));
    f.slot_present = false;
    TEST_ASSERT_EQUAL(PP_FAIL_REMOVED, pp_decide(&f));
}

void test_stale_with_the_engine_absent_or_stalled_plays_the_original(void)
{
    pp_facts_t f = ready_facts();
    f.check = FXJ_STALE;
    f.engine_ok = false;
    TEST_ASSERT_EQUAL(PP_PLAY_ORIGINAL, pp_decide(&f));
    TEST_ASSERT_TRUE(pp_no_fx(&f));                   /* the ack says NO_FX */
}

void test_a_stale_effect_file_is_prepared(void)
{
    pp_facts_t f = ready_facts();
    f.check = FXJ_STALE;
    TEST_ASSERT_EQUAL(PP_PREPARE, pp_decide(&f));
}

void test_just_made_but_stale_plays_the_original_once(void)
{
    pp_facts_t f = ready_facts();
    f.check = FXJ_STALE;
    f.retry_done = true;                              /* it was made a moment ago */
    TEST_ASSERT_EQUAL(PP_PLAY_ORIGINAL_NOT_VALID, pp_decide(&f));
}

void test_play_resume_or_an_effect_change_clears_retry_done(void)
{
    pp_ctx_t c = { .retry_done = true, .no_slot_retried = true };
    pp_new_request(&c);
    TEST_ASSERT_FALSE(c.retry_done);
    TEST_ASSERT_FALSE(c.no_slot_retried);
}

/* ---------- 2. pp_on_waited_end ---------- */

void test_a_made_file_plays(void)
{
    TEST_ASSERT_EQUAL(PP_END_PLAY, pp_on_waited_end(FXJ_WANT_DONE, FXJ_FAIL_NONE, false, true));
}

void test_no_engine_on_the_waited_job_plays_the_original(void)
{
    TEST_ASSERT_EQUAL(PP_END_ORIGINAL_AT_POS, pp_on_waited_end(FXJ_WANT_FAILED, FXJ_FAIL_NO_ENGINE, false, true));
}

void test_a_bad_source_or_chunk_on_the_waited_job_plays_the_original(void)
{
    TEST_ASSERT_EQUAL(PP_END_ORIGINAL_AT_POS, pp_on_waited_end(FXJ_WANT_FAILED, FXJ_FAIL_SOURCE, false, true));
    TEST_ASSERT_EQUAL(PP_END_ORIGINAL_AT_POS, pp_on_waited_end(FXJ_WANT_FAILED, FXJ_FAIL_BAD_REQUEST, false, true));
}

void test_giving_up_plays_the_original_at_the_position(void)
{
    TEST_ASSERT_EQUAL(PP_END_ORIGINAL_AT_POS, pp_on_waited_end(FXJ_WANT_GAVE_UP, FXJ_FAIL_NONE, false, true));
}

void test_no_slot_retries_once_then_is_refused(void)
{
    TEST_ASSERT_EQUAL(PP_END_RETRY_AFTER_REMOUNT, pp_on_waited_end(FXJ_WANT_FAILED, FXJ_FAIL_NO_SLOT, false, true));
    TEST_ASSERT_EQUAL(PP_END_FAULT_REFUSED, pp_on_waited_end(FXJ_WANT_FAILED, FXJ_FAIL_NO_SLOT, true, true));
    TEST_ASSERT_EQUAL(PP_END_FAULT_REFUSED, pp_on_waited_end(FXJ_WANT_FAILED, FXJ_FAIL_REFUSED, false, true));
}

void test_a_waited_card_error_with_an_empty_slot_is_card_removed(void)
{
    TEST_ASSERT_EQUAL(PP_END_FAULT_REMOVED, pp_on_waited_end(FXJ_WANT_FAILED, FXJ_FAIL_CARD_WRITE, false, false));
    TEST_ASSERT_EQUAL(PP_END_FAULT_REMOVED, pp_on_waited_end(FXJ_WANT_FAILED, FXJ_FAIL_CARD_READ, false, false));
}

void test_a_full_card_is_its_own_notice(void)
{
    TEST_ASSERT_EQUAL(PP_END_FAULT_FULL, pp_on_waited_end(FXJ_WANT_FAILED, FXJ_FAIL_FULL, false, true));
}

void test_write_and_read_errors_are_reported(void)
{
    TEST_ASSERT_EQUAL(PP_END_FAULT_WRITE, pp_on_waited_end(FXJ_WANT_FAILED, FXJ_FAIL_CARD_WRITE, false, true));
    TEST_ASSERT_EQUAL(PP_END_FAULT_READ, pp_on_waited_end(FXJ_WANT_FAILED, FXJ_FAIL_CARD_READ, false, true));
}

/* ---------- 3. Position and offsets ---------- */

void test_the_position_counts_only_the_samples_already_heard(void)
{
    /* 4.000 s of a 32 kHz source played: 128 000 samples. Read so far:
     * 128 000 samples + one 4 KB chunk not yet queued (2048 samples) and
     * 16 blocks queued (1024 samples): bytes_read covers all of them. */
    const uint32_t bytes_read = (128000U + 1024U + 2048U) * 2U;
    const uint32_t played = pp_played_samples(bytes_read, 4096U, 0U, 16U);
    TEST_ASSERT_EQUAL_UINT32(128000U, played);
    TEST_ASSERT_EQUAL_UINT32(2000U, pp_pos_blocks(played, PP_SPB_SOURCE));
}

void test_an_effect_switch_carries_on_at_the_same_moment(void)
{
    /* 2000 source blocks: sample 192 000 of the effect file of a 32 kHz
     * source (4.000 s at 48 kHz), sample 128 000 of the source itself. */
    TEST_ASSERT_EQUAL_UINT32(192000U * 2U, pp_fx_offset(2000U, PP_SPB_FX_OF_32K, 960000U));
    TEST_ASSERT_EQUAL_UINT32(128000U * 2U, pp_original_offset(2000U, 640000U));
    /* and back: 4.000 s of the effect file is 2000 source blocks again */
    TEST_ASSERT_EQUAL_UINT32(2000U, pp_pos_blocks(192000U, PP_SPB_FX_OF_32K));
}

void test_an_offset_past_the_end_starts_at_zero(void)
{
    TEST_ASSERT_EQUAL_UINT32(0U, pp_original_offset(5000U, 640000U));      /* 640 000 B = 5000 blocks: the end */
    TEST_ASSERT_EQUAL_UINT32(0U, pp_fx_offset(5000U, PP_SPB_FX_OF_32K, 960000U));
    TEST_ASSERT_EQUAL_UINT32(4999U * 128U, pp_original_offset(4999U, 640000U));
}

void test_played_is_never_negative(void)
{
    /* Right after a start, more is queued and buffered than was "played". */
    TEST_ASSERT_EQUAL_UINT32(0U, pp_played_samples(4096U, 4096U, 2048U, 16U));
    TEST_ASSERT_EQUAL_UINT32(0U, pp_played_samples(0U, 4096U, 0U, 0U));
    /* Right after a loop rewind, bytes_read starts again at 0: 512 samples
     * handed out since, but 16 blocks (1024 samples) still queued, half of
     * them from the last pass. */
    TEST_ASSERT_EQUAL_UINT32(0U, pp_played_samples(1024U, 0U, 0U, 16U));
}

int main(void)
{
    UNITY_BEGIN();
    RUN_TEST(test_the_same_pair_being_made_is_adopted);
    RUN_TEST(test_another_pair_needs_the_source_facts_first);
    RUN_TEST(test_an_effect_switch_while_preparing_is_another_pair);
    RUN_TEST(test_files_jack_cannot_play_are_refused_as_today);
    RUN_TEST(test_a_read_fail_with_an_empty_slot_is_card_removed);
    RUN_TEST(test_no_effect_or_a_file_without_effects_plays_the_original);
    RUN_TEST(test_a_valid_effect_file_plays_even_while_the_engine_is_stalled);
    RUN_TEST(test_a_check_io_error_is_a_read_fault);
    RUN_TEST(test_stale_with_the_engine_absent_or_stalled_plays_the_original);
    RUN_TEST(test_a_stale_effect_file_is_prepared);
    RUN_TEST(test_just_made_but_stale_plays_the_original_once);
    RUN_TEST(test_play_resume_or_an_effect_change_clears_retry_done);
    RUN_TEST(test_a_made_file_plays);
    RUN_TEST(test_no_engine_on_the_waited_job_plays_the_original);
    RUN_TEST(test_a_bad_source_or_chunk_on_the_waited_job_plays_the_original);
    RUN_TEST(test_giving_up_plays_the_original_at_the_position);
    RUN_TEST(test_no_slot_retries_once_then_is_refused);
    RUN_TEST(test_a_waited_card_error_with_an_empty_slot_is_card_removed);
    RUN_TEST(test_a_full_card_is_its_own_notice);
    RUN_TEST(test_write_and_read_errors_are_reported);
    RUN_TEST(test_the_position_counts_only_the_samples_already_heard);
    RUN_TEST(test_an_effect_switch_carries_on_at_the_same_moment);
    RUN_TEST(test_an_offset_past_the_end_starts_at_zero);
    RUN_TEST(test_played_is_never_negative);
    return UNITY_END();
}
